contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(recipient != address(0), "zero recipient");
        require(msg.sender == c.owner(), "caller is not owner");
        require(address(this).balance >= 0, "no value needed");

        uint256 preRecipient = recipient.balance;
        uint256 preContract = address(c).balance;

        bool reverted;
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || recipient.balance == preRecipient + preContract);
    }

    receive() external payable {}
}

