// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable as C} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function _run(address recipient) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(recipient != address(0));
        vm.assume(msg.sender == c.owner());
        vm.assume(address(this).balance >= 0);
        uint256 preRecipient = recipient.balance;
        uint256 preContract = address(c).balance;
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || recipient.balance == preRecipient + preContract);
    }

    function testFuzz_run(address recipient) public {
        _run(recipient);
    }

    receive() external payable {}
}
